function locationStock(partId,location='main',exclude,data=db){
 let part=data.parts.find(p=>p.id===partId);if(!part)return 0;
 let qty=location==='main'?Number(part.opening||0):0;
 for(let purchase of data.purchases||[])if(purchase.id!==exclude&&purchase.status!=='Cancelled'&&(purchase.stockLocation||'main')===location)for(let line of purchase.partLines||[])if(line.part===partId)qty+=Number(line.qty||0);
 for(let movement of data.stockMovements||[])if(movement.part===partId){if(movement.kind==='opening'&&location==='godown')qty+=Number(movement.qty);if(movement.kind==='transfer')qty+=Number(movement.qty)*(location==='main'?1:-1)}
 if(location==='main')for(let bill of [...data.jobs,...data.sales])if(bill.id!==exclude&&bill.status!=='Cancelled')for(let line of bill.partLines||[])if(line.part===partId)qty-=Number(line.qty||0);
 return round(qty);
}
stock=function(id,exclude){return locationStock(id,'main',exclude)};
