 let serial=1;while(db.stockMovements.some(m=>m.id==='MOV-'+String(serial).padStart(5,'0')))serial++;
 entry={...entry,id:'MOV-'+String(serial).padStart(5,'0'),createdAt:new Date().toISOString()};db.stockMovements.push(entry);
